-- Rentals Phase 45: maintenance triage, assignment and SLA control.
begin;
create table public.rental_maintenance_assignments(id uuid primary key default gen_random_uuid(),request_id uuid not null unique references public.rental_maintenance_requests(id),organisation_id uuid not null references public.organisations(id),assignee_name text not null check(length(btrim(assignee_name))>0),assignee_contact text,assigned_by uuid not null references auth.users(id),assigned_at timestamptz not null default now(),sla_due_at timestamptz not null,triage_notes text,priority_at_assignment text not null check(priority_at_assignment in('emergency','urgent','routine')),status text not null default 'assigned' check(status in('assigned','accepted','in_progress','completed','cancelled')));
create index rental_maintenance_assignments_sla_idx on public.rental_maintenance_assignments(organisation_id,status,sla_due_at);alter table public.rental_maintenance_assignments enable row level security;revoke all on public.rental_maintenance_assignments from anon,authenticated;grant select on public.rental_maintenance_assignments to authenticated;create policy rental_maintenance_assignments_read on public.rental_maintenance_assignments for select to authenticated using(exists(select 1 from public.rental_maintenance_requests r join public.rental_properties p on p.id=r.property_id where r.id=request_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create or replace function public.rental_triage_maintenance_request(p_request uuid,p_priority text,p_notes text,p_assignee_name text,p_assignee_contact text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.rental_maintenance_requests%rowtype;aid uuid;due_at timestamptz;begin if auth.uid() is null or p_priority not in('emergency','urgent','routine') or length(btrim(coalesce(p_assignee_name,'')))=0 then raise exception 'Priority and assignee are required';end if;select * into r from public.rental_maintenance_requests where id=p_request for update;if not found or not exists(select 1 from public.rental_properties p where p.id=r.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;if r.status in('resolved','cancelled') then raise exception 'Closed requests cannot be assigned';end if;due_at:=now()+case p_priority when 'emergency' then interval '4 hours' when 'urgent' then interval '24 hours' else interval '72 hours' end;update public.rental_maintenance_requests set priority=p_priority,status='assigned' where id=r.id;insert into public.rental_maintenance_assignments(request_id,organisation_id,assignee_name,assignee_contact,assigned_by,sla_due_at,triage_notes,priority_at_assignment) values(r.id,r.organisation_id,btrim(p_assignee_name),nullif(btrim(coalesce(p_assignee_contact,'')),''),auth.uid(),due_at,nullif(btrim(coalesce(p_notes,'')),''),p_priority) on conflict(request_id) do update set assignee_name=excluded.assignee_name,assignee_contact=excluded.assignee_contact,assigned_by=excluded.assigned_by,assigned_at=now(),sla_due_at=excluded.sla_due_at,triage_notes=excluded.triage_notes,priority_at_assignment=excluded.priority_at_assignment,status='assigned' returning id into aid;return jsonb_build_object('request_id',r.id,'assignment_id',aid,'sla_due_at',due_at,'status','assigned');end$$;
create or replace function public.rental_get_maintenance_queue(p_limit int default 200) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('request_id',q.id,'property_id',q.property_id,'unit_id',q.unit_id,'category',q.category,'priority',q.priority,'status',q.status,'reported_at',q.reported_at,'assignee_name',q.assignee_name,'sla_due_at',q.sla_due_at,'sla_breached',q.sla_due_at<now() and q.assignment_status not in('completed','cancelled')) order by case when q.sla_due_at<now() then 0 else 1 end,q.sla_due_at nulls last,q.reported_at), '[]'::jsonb) from (select r.*,a.assignee_name,a.sla_due_at,a.status as assignment_status from public.rental_maintenance_requests r join public.rental_properties p on p.id=r.property_id left join public.rental_maintenance_assignments a on a.request_id=r.id where r.status not in('resolved','cancelled') and public.rental_branch_access(p.organisation_id,p.branch_id) order by r.reported_at desc limit greatest(1,least(coalesce(p_limit,200),1000))) q$$;
revoke execute on function public.rental_triage_maintenance_request(uuid,text,text,text,text),public.rental_get_maintenance_queue(int) from public,anon;grant execute on function public.rental_triage_maintenance_request(uuid,text,text,text,text),public.rental_get_maintenance_queue(int) to authenticated;commit;
